/* per-item row inside a turn's activity block */
function renderActivityItem(item) {
  switch (item.type) {
    case 'commandExecution': {
      const cmd = (item.command || '').trim();
      const firstLine = cmd.split('\n')[0];
      const label = firstLine.length > 72 ? firstLine.slice(0, 70) + '…' : (firstLine || '命令');
      const row = activityRow(label, { expandable: true, icon: ICON16.terminal, title: cmd });
      const outer = detailWrap(() => [
        commandCard({
          label: item.status === 'failed' ? 'Shell · failed' : 'Shell',
          command: cmd,
          output: item.output || '',
          exitCode: item.exitCode,
          status: item.status,
        }),
      ], 'inline');
      const btn = row.querySelector('button');
      const chev = row.querySelector('[data-chev]');
      btn.addEventListener('click', () => toggleDetail(outer, chev, btn));
      const box = document.createElement('div');
      box.className = 'min-w-0 text-size-chat relative overflow-visible py-0';
      const stack = document.createElement('div');
      stack.className = 'flex min-w-0 flex-col relative overflow-clip';
      stack.append(row, outer);
      box.appendChild(stack);
      return box;
    }
    case 'mcpToolCall': {
      const label = `${item.server || 'mcp'} · ${item.tool || ''}`;
      const row = activityRow(label, { expandable: true, icon: ICON16.tool, title: label });
      const outer = detailWrap(() => [
        commandCard({
          label: `${item.server || 'mcp'} / ${item.tool || ''}`,
          command: item.arguments || '',
          output: item.result || '',
          status: item.status,
        }),
      ], 'inline');
      const btn = row.querySelector('button');
      const chev = row.querySelector('[data-chev]');
      btn.addEventListener('click', () => toggleDetail(outer, chev, btn));
      const box = document.createElement('div');
      box.className = 'min-w-0 text-size-chat relative overflow-visible py-0';
      const stack = document.createElement('div');
      stack.className = 'flex min-w-0 flex-col relative overflow-clip';
      stack.append(row, outer);
      box.appendChild(stack);
      return box;
    }
    case 'reasoning': {
      const lines = (item.summary && item.summary.length ? item.summary : item.content || []).filter(Boolean);
      if (!lines.length) return null;
      const label = lines[0].replace(/\*\*/g, '').slice(0, 72) || '思考';
      const row = activityRow(label, { expandable: true, icon: ICON16.sparkle });
      const outer = detailWrap(() => lines.slice(1).map(l => {
        const d = document.createElement('div');
        d.className = 'min-w-0 text-size-chat relative overflow-visible py-0 text-codex-description';
        d.textContent = String(l).replace(/\*\*/g, '');
        return d;
      }), 'inline');
      const btn = row.querySelector('button');
      const chev = row.querySelector('[data-chev]');
      btn.addEventListener('click', () => toggleDetail(outer, chev, btn));
      const box = document.createElement('div');
      box.className = 'min-w-0 text-size-chat relative overflow-visible py-0';
      const stack = document.createElement('div');
      stack.className = 'flex min-w-0 flex-col relative overflow-clip';
      stack.append(row, outer);
      box.appendChild(stack);
      return box;
    }
    case 'subAgentActivity': {
      const path = item.agentPath || '';
      const name = path ? path.split('/').filter(Boolean).pop() : (item.agentThreadId || '').slice(0, 8);
      const verb = { started: '已创建聊天', completed: '聊天已完成', interrupted: '聊天已中断', interacted: '已交互' }[item.kind] || '已创建聊天';
      const row = activityRow(`${verb} · ${name}`, { expandable: false, icon: ICON16.agent, title: path });
      const box = document.createElement('div');
      box.className = 'min-w-0 text-size-chat relative overflow-visible py-0';
      box.appendChild(row);
      return box;
    }
    case 'collabAgentToolCall': {
      const verb = {
        spawnAgent: '已创建聊天', sendInput: '已发送输入', resumeAgent: '已恢复聊天',
        wait: '等待聊天', closeAgent: '已关闭聊天',
      }[item.tool] || '已创建聊天';
      const row = activityRow(verb, { expandable: false, icon: ICON16.agent });
      const box = document.createElement('div');
      box.className = 'min-w-0 text-size-chat relative overflow-visible py-0';
      box.appendChild(row);
      return box;
    }
    case 'contextCompaction': {
      const box = document.createElement('div');
      box.className = 'min-w-0 text-size-chat relative overflow-visible py-0';
      box.appendChild(activityRow('上下文已自动压缩', { icon: ICON16.compact }));
      return box;
    }
    case 'imageView': {
      const box = document.createElement('div');
      box.className = 'min-w-0 text-size-chat relative overflow-visible py-0';
      box.appendChild(activityRow(`已打开文件 · ${shortPath(item.path)}`, { icon: ICON16.file, title: item.path }));
      return box;
    }
    case 'sleep': {
      const box = document.createElement('div');
      box.className = 'min-w-0 text-size-chat relative overflow-visible py-0';
      box.appendChild(activityRow(`等待 ${fmtDuration(item.durationMs)}`, { icon: ICON16.compact }));
      return box;
    }
    default: return null;
  }
}

/* the turn-level summary line + its detail */
function renderActivityBlock(items) {
  const wrap = document.createElement('div');
  wrap.className = 'flex flex-col';

  const labels = [];
  for (const it of items) {
    const l = ACTIVITY_LABEL[it.type];
    if (l && !labels.includes(l)) labels.push(l);
  }
  const summary = labels.join('') || '活动';

  const row = activityRow(summary, { expandable: true, icon: activityIcon(items[0].type) });
  const outer = detailWrap(() => items.map(renderActivityItem));
  const btn = row.querySelector('button');
  const chev = row.querySelector('[data-chev]');
  btn.addEventListener('click', () => toggleDetail(outer, chev, btn));

  wrap.append(row, outer);
  return wrap;
}

/* 「用时 X」— the real app's expandable duration button */
function renderDuration(ms, items) {
  const wrap = document.createElement('div');
  wrap.className = 'flex flex-col';
  const btn = document.createElement('button');
  btn.type = 'button';
  btn.className = 'no-drag cursor-interaction focus-visible:outline-hidden whitespace-nowrap flex border gap-1 rounded-md text-tertiary not-disabled:not-aria-disabled:hover:bg-transparent data-[state=open]:bg-transparent not-disabled:not-aria-disabled:hover:text-default border-transparent border-0 p-0 inline-flex max-w-full text-size-chat flex-wrap';
  btn.setAttribute('aria-expanded', 'false');
  btn.innerHTML = `<span><span class="tabular-nums text-inherit">用时 ${fmtDuration(ms)}</span></span>${ICON16.chevron}`;
  const outer = detailWrap(() => items.map(renderActivityItem));
  btn.addEventListener('click', () => {
    const expanded = btn.getAttribute('aria-expanded') === 'true';
    toggleDetail(outer, btn.querySelector('svg'), btn);
    btn.setAttribute('aria-expanded', expanded ? 'false' : 'true');
  });
  wrap.append(btn, outer);
  return wrap;
}

function renderTurn(turn) {
  const wrap = document.createElement('div');
  wrap.className = 'flex flex-col gap-[var(--conversation-item-gap,16px)] pb-6';

  const items = turn.items || [];
  const messages = items.filter(i => i.type === 'userMessage' || i.type === 'agentMessage');
  const cards = items.filter(i => i.type === 'fileChange');
  const activity = items.filter(i => !['userMessage', 'agentMessage', 'fileChange'].includes(i.type));

  for (const m of messages) {
    const n = m.type === 'userMessage' ? renderUserMessage(m, turn.startedAt) : renderAssistantMessage(m);
    if (n) wrap.appendChild(n);
  }

  if (activity.length) wrap.appendChild(renderActivityBlock(activity));

  for (const c of cards) {
    const n = renderFileChange(c);
    if (n) wrap.appendChild(n);
  }

  if (turn.durationMs) wrap.appendChild(renderDuration(turn.durationMs, activity));

  return wrap;
}

/* file-change card — classes copied verbatim from the live renderer */
function renderFileChange(item) {
  const changes = item.changes || [];
  if (!changes.length) return null;

  let add = 0, del = 0;
  for (const c of changes) {
    if (!c.diff) continue;
    for (const line of String(c.diff).split('\n')) {
      if (line.startsWith('+') && !line.startsWith('+++')) add++;
      else if (line.startsWith('-') && !line.startsWith('---')) del++;
    }
  }

  const wrap = document.createElement('div');
  wrap.className = 'flex flex-col overflow-hidden font-sans text-default [--resource-card-row-padding-x:0.75rem] max-w-[min(100%,var(--resource-card-max-width,100%))] bg-surface-elevated-secondary/50 rounded-lg mb-2 text-base [--turn-diff-row-padding-y:0.25rem]';

  const head = document.createElement('div');
  head.className = 'group/turn-diff-header relative';
  head.innerHTML =
    '<button aria-label="查看已更改的文件" class="absolute inset-0 cursor-interaction rounded-lg bg-transparent group-hover/turn-diff-header:bg-background-secondary-ghost-hover/30 focus-visible:ring-2 focus-visible:ring-ring focus-visible:outline-none focus-visible:ring-inset" type="button"></button>' +
    '<span class="flex min-w-0 items-center text-start gap-2.5 px-[var(--resource-card-row-padding-x)] py-3 pointer-events-none relative z-10">' +
      '<span class="flex size-10 shrink-0 items-center justify-center rounded-lg bg-surface-secondary/92 text-secondary">' +
        '<svg width="24" height="24" viewBox="0 0 24 24" fill="none" aria-hidden="true"><path d="M14.5 15.25a.75.75 0 010 1.5h-5a.75.75 0 010-1.5h5z" fill="currentColor"/><path d="M12 6.75c.41 0 .75.34.75.75v1.75h1.75a.75.75 0 010 1.5h-1.75v1.75a.75.75 0 01-1.5 0v-1.75H9.5a.75.75 0 010-1.5h1.75V7.5c0-.41.34-.75.75-.75z" fill="currentColor"/><path fill-rule="evenodd" clip-rule="evenodd" d="M17.2 3.25a3.55 3.55 0 013.55 3.55v10.4a3.55 3.55 0 01-3.55 3.55H6.8a3.55 3.55 0 01-3.55-3.55V6.8A3.55 3.55 0 016.8 3.25h10.4zM6.8 4.75A2.05 2.05 0 004.75 6.8v10.4a2.05 2.05 0 002.05 2.05h10.4a2.05 2.05 0 002.05-2.05V6.8a2.05 2.05 0 00-2.05-2.05H6.8z" fill="currentColor"/></svg>' +
      '</span>' +
      '<span class="flex min-w-0 flex-1 flex-col">' +
        `<span class="truncate text-default text-size-chat font-medium">已编辑 ${changes.length} 个文件</span>` +
        `<span class="truncate text-secondary text-size-chat-sm">${add ? `+${add}` : ''}${add && del ? ' ' : ''}${del ? `-${del}` : ''}</span>` +
      '</span>' +
      '<span class="pointer-events-auto flex items-center gap-1 opacity-0 group-hover/turn-diff-header:opacity-100 transition-opacity">' +
        '<button type="button" class="rounded-md px-2 py-1 text-xs text-secondary hover:bg-secondary-ghost-hover">撤销</button>' +
        '<button type="button" class="rounded-md px-2 py-1 text-xs text-secondary hover:bg-secondary-ghost-hover">查看变更</button>' +
      '</span>' +
    '</span>';

  const row = (c) => {
    const kt = c.kind || 'update';
    const full = String(c.path || '');
    const norm = full.replace(/\\/g, '/');
    const idx = norm.lastIndexOf('/');
    const dir = idx >= 0 ? norm.slice(0, idx + 1) : '';
    const name = idx >= 0 ? norm.slice(idx + 1) : norm;
    return `<div class="group/turn-diff-file-row [contain-intrinsic-size:auto_36px] [content-visibility:auto]">` +
      `<div type="button" aria-haspopup="dialog" aria-expanded="false" data-state="closed">` +
      `<button class="flex h-9 w-full cursor-interaction items-center gap-2 bg-surface/70 px-[var(--resource-card-row-padding-x)] py-[var(--turn-diff-row-padding-y)] text-start text-size-chat group-last/turn-diff-file-row:rounded-b-lg hover:bg-background-secondary-ghost-hover/60 focus-visible:ring-2 focus-visible:ring-ring focus-visible:outline-none focus-visible:ring-inset" type="button">` +
      `<span class="sr-only">${esc(full)}</span>` +
      `<span aria-hidden="true" class="flex min-w-0 flex-1 items-center">` +
        `<span class="min-w-0 truncate text-codex-description">${esc(dir)}</span>` +
        `<span class="max-w-full shrink-0 truncate text-default">${esc(name)}</span>` +
      `</span>` +
      `<span data-thread-find-skip="true" class="inline-flex items-center gap-1 leading-none disambiguated-digits tabular-nums tracking-tight">` +
        (c.binary
          ? '<span class="flex shrink-0 items-center text-codex-description">binary</span>'
          : `${kt === 'add' ? '' : ''}<span class="flex shrink-0 items-center text-codex-git-added">+</span><span class="flex shrink-0 items-center text-codex-git-deleted">-</span>`) +
      `</span></button></div></div>`;
  };

  const body = document.createElement('div');
  body.className = 'flex flex-col divide-y divide-border';
  const visible = changes.slice(0, 8);
  const rest = changes.slice(8);
  body.innerHTML = visible.map(row).join('') +
    (rest.length ? `<div data-rest class="hidden flex-col divide-y divide-border">${rest.map(row).join('')}</div>` : '');
  wrap.appendChild(head);
  wrap.appendChild(body);

  if (rest.length) {
    const more = document.createElement('button');
    more.type = 'button';
    more.setAttribute('aria-expanded', 'false');
    more.className = 'flex h-9 w-full cursor-interaction items-center rounded-b-lg px-[var(--resource-card-row-padding-x)] py-[var(--turn-diff-row-padding-y)] text-start text-size-chat text-default hover:bg-background-secondary-ghost-hover/30 focus-visible:ring-2 focus-visible:ring-ring focus-visible:outline-none focus-visible:ring-inset';
    more.innerHTML = `<span class="inline-flex min-w-0 items-center gap-2"><span class="truncate">再显示 ${rest.length} 个文件</span>${ICON16.chevron}</span>`;
    more.addEventListener('click', () => {
      const r = $('[data-rest]', wrap);
      if (r) r.classList.remove('hidden');
      more.remove();
    });
    wrap.appendChild(more);
  }

  return wrap;
}

/* ---- user message: right-aligned bubble, markup verbatim from the renderer ---- */
function renderUserMessage(item, ts) {
  const text = item.text || '';
  const wrap = document.createElement('div');
  wrap.className = 'flex flex-col items-end gap-2';
  wrap.innerHTML =
    '<div class="group/user-message flex w-full flex-col gap-1 items-end">' +
      '<div class="flex w-full items-center gap-1 justify-end">' +
        '<div class="turn-action-controls opacity-0 group-has-[:focus-visible]/user-message:opacity-100 group-hover/user-message:opacity-100 [@media(hover:none)]:opacity-100">' +
          `<button type="button" class="no-drag cursor-interaction focus-visible:outline-hidden whitespace-nowrap flex border gap-1 rounded-full electron:rounded-md text-tertiary not-disabled:not-aria-disabled:hover:bg-secondary-ghost-hover border-transparent electron:p-1 button-icon items-center justify-center p-0.5" aria-label="复制消息" data-copy>${ICON16.copy}</button>` +
        '</div>' +
        '<div data-user-message-bubble="true" class="bg-user-message text-user-message min-w-0 max-w-(--user-chat-width) overflow-hidden break-words px-(--thread-content-margin) bubble-vBnidZ py-2.5 rounded-2xl relative text-start">' +
          '<div class="flex flex-col items-end gap-1">' +
            '<div class="relative w-full min-w-0 text-size-chat leading-relaxed">' +
              '<div data-search-result-target=""><div><div class="text-size-chat">' +
                `<div data-markdown-text-tone="user-message" class="MarkdownRoot-rZKhxa [&>*:first-child]:mt-0 [&>*:last-child]:mb-0 rich-text-user-turn rich-text-serialized-paragraphs" style="--markdown-link-color: currentColor">${renderMarkdown(text)}</div>` +
              '</div></div></div>' +
            '</div>' +
          '</div>' +
        '</div>' +
      '</div>' +
    '</div>';
  wireCopy(wrap, text);
  return wrap;
}

/* ---- assistant message: no bubble, plain markdown ---- */
function renderAssistantMessage(item) {
  const text = item.text || '';
  const wrap = document.createElement('div');
  wrap.className = 'flex flex-col';
  wrap.innerHTML =
    '<div class="group flex min-w-0 flex-col">' +
      '<h4 class="sr-only m-0 select-none" data-conversation-role="assistant"><span>ChatGPT 说：</span></h4>' +
      '<div data-markdown-text-style="assistant-message" class="MarkdownRoot-rZKhxa [&>*:first-child]:mt-0 [&>*:last-child]:mb-0 [&>ol:first-child]:mt-0 [&>ul:first-child]:mt-0" style="--markdown-link-color: currentColor">' +
        renderMarkdown(text) +
      '</div>' +
    '</div>';
  return wrap;
}

function wireCopy(root, text) {
  const btn = $('[data-copy]', root);
  if (!btn) return;
  btn.addEventListener('click', async (e) => {
    e.stopPropagation();
    try {
      await navigator.clipboard.writeText(text || '');
      btn.innerHTML = ICON.check;
      setTimeout(() => { btn.innerHTML = ICON16.copy; }, 1200);
    } catch { }
  });
}

function renderItem(item) {
  switch (item.type) {
    case 'userMessage': return renderUserMessage(item, null);
    case 'agentMessage': return renderAssistantMessage(item);
    case 'fileChange': return renderFileChange(item);
    default: return renderActivityItem(item);
  }
}


function renderFooter() {
  const wrap = document.createElement('div');
  wrap.className = 'h-4';
  return wrap;
}

function wireCopy(root, text) {
  const btn = $('[data-copy]', root);
  if (!btn) return;
  btn.addEventListener('click', async (e) => {
    e.stopPropagation();
    try {
      await navigator.clipboard.writeText(text || '');
      btn.innerHTML = ICON.check;
      setTimeout(() => { btn.innerHTML = ICON.copy; }, 1200);
    } catch { }
  });
}

/* ------------------------------------------------------------------ composer */
function wireComposer(root) {
  const editor = $('[contenteditable="true"]', root);
  if (!editor) return;
  const sendBtn = $$('button', root).find(b => /send|发送/i.test(b.getAttribute('aria-label') || '') || /ArrowUp|arrow-up/i.test(b.innerHTML))
    || $$('button', root).slice(-1)[0];

  const updatePlaceholder = () => {
    const p = $('[data-placeholder]', editor);
    if (!p) return;
    if ((editor.textContent || '').trim()) p.removeAttribute('data-placeholder');
    else p.setAttribute('data-placeholder', '随心输入');
  };

  editor.addEventListener('input', updatePlaceholder);
  editor.addEventListener('keydown', (e) => {
    if (e.key === 'Enter' && !e.shiftKey) {
      e.preventDefault();
      send();
    }
  });

  function send() {
    const text = (editor.textContent || '').trim();
    if (!text) return;
    editor.innerHTML = '<p data-empty-paragraph="true" data-placeholder="随心输入" class="placeholder before:composer-placeholder"><br class="ProseMirror-trailingBreak"></p>';
    updatePlaceholder();

    if (state.view !== 'thread' || !state.current) {
      const first = state.threads[0];
      if (first) location.hash = '#/t/' + first.id;
      return;
    }
    const ts = Math.floor(Date.now() / 1000);
    state.sent.push({ threadId: state.current.id, text, ts });
    const host = $('#turns');
    host.appendChild(renderUserMessage({ text, id: 'local' + ts }, ts));
    const reply = document.createElement('div');
    reply.className = 'group/agent-message flex min-w-0 flex-col gap-1';
    reply.innerHTML = `<div class="MarkdownRoot-rZKhxa text-size-chat leading-relaxed">
      <p class="Paragraph-kKnbIo">这是<b>本地复刻前端</b>，没有接后端模型。你的输入已作为一条消息渲染进对话流，用来验证消息气泡、滚动与布局行为。</p></div>`;
    host.appendChild(reply);
    const tr = $('#transcript');
    tr.scrollTop = tr.scrollHeight;
  }

  if (sendBtn) sendBtn.addEventListener('click', send);

  // model picker + dropdowns inside the composer
  wireComposerDropdowns(root);
}

function wireComposerDropdowns(root) {
  const triggers = $$('[aria-haspopup="menu"], [aria-haspopup="listbox"]', root);
  for (const t of triggers) {
    t.addEventListener('click', (e) => {
      e.preventDefault();
      openMenu(t, menuItemsFor(t));
    });
  }
}

function menuItemsFor(trigger) {
  const label = (trigger.textContent || '').trim();
  if (/Astra|Sol|Luna|Terra|5\.5|6\./.test(label)) {
    return ['默认', '推荐模型集', '6.1 Sol', '6 Astra', '6 Sol', '6 Luna', '5.6 Sol', '6.1 Terra', '5.6 Terra', '5.6 Luna', '5.5'];
  }
  if (/极高|极低|轻度|中|高|Max|Ultra/.test(label)) {
    return ['无', '极低', '轻度', '中', '高', '极高', 'Max', 'Ultra'];
  }
  if (/完全访问|权限/.test(label)) {
    return ['只读', '需要确认', '自动编辑', '完全访问'];
  }
  return ['默认'];
}

function openMenu(trigger, items) {
  closeMenu();
  const rect = trigger.getBoundingClientRect();
  const menu = document.createElement('div');
  menu.id = 'popover-menu';
  menu.setAttribute('role', 'menu');
  menu.className = 'fixed z-50 m-px flex max-h-[60vh] select-none flex-col overflow-y-auto rounded-xl border border-subtle bg-surface-elevated-secondary p-1 text-sm shadow-lg';
  menu.style.minWidth = '200px';
  menu.style.left = Math.max(8, Math.min(rect.left, window.innerWidth - 240)) + 'px';
  menu.style.bottom = (window.innerHeight - rect.top + 6) + 'px';
  menu.innerHTML = items.map((it, i) =>
    `<button role="menuitem" data-i="${i}" class="flex w-full items-center gap-2 rounded-lg px-2.5 py-1.5 text-start hover:bg-secondary-ghost-hover">${esc(it)}</button>`
  ).join('');
  document.body.appendChild(menu);
  menu.addEventListener('click', (e) => {
    const b = e.target.closest('[data-i]');
    if (!b) return;
    trigger.textContent = items[Number(b.dataset.i)];
    closeMenu();
  });
  setTimeout(() => document.addEventListener('click', closeMenu, { once: true }), 0);
}

function closeMenu() {
  const m = $('#popover-menu');
  if (m) m.remove();
}

/* -------------------------------------------------------------------- search */
function buildSearchDialog() {
  const dlg = document.createElement('div');
  dlg.id = 'search-dialog';
  dlg.className = 'hidden fixed inset-0 z-[60] flex items-start justify-center bg-black/20 pt-[12vh]';
  dlg.innerHTML = `
    <div class="codex-dialog w-[min(760px,92vw)] overflow-hidden rounded-2xl border border-subtle bg-surface-elevated-secondary shadow-2xl">
      <div class="flex items-center gap-2 border-b border-subtle px-4 py-3">
        <span class="text-tertiary">${ICON.search}</span>
        <input id="search-input" class="min-w-0 flex-1 bg-transparent text-base outline-none" placeholder="搜索聊天、操作和项目文件" />
        <span class="text-xs text-tertiary">Esc 关闭</span>
      </div>
      <div class="flex gap-1 px-3 pt-2 text-xs text-tertiary">
        <span class="rounded-md px-2 py-1 bg-secondary-ghost-hover text-default">聊天</span>
        <span class="rounded-md px-2 py-1">文件</span>
        <span class="rounded-md px-2 py-1">文本</span>
      </div>
      <div id="search-results" class="max-h-[52vh] overflow-y-auto p-2"></div>
    </div>`;
  document.body.appendChild(dlg);

  const input = $('#search-input', dlg);
  input.addEventListener('input', () => renderSearchResults(input.value));
  dlg.addEventListener('click', (e) => { if (e.target === dlg) closeSearch(); });
  renderSearchResults('');
}

function renderSearchResults(q) {
  const host = $('#search-results');
  const needle = q.trim().toLowerCase();
  const list = state.threads
    .filter(t => !needle
      || threadTitle(t).toLowerCase().includes(needle)
      || (t.cwd || '').toLowerCase().includes(needle))
    .slice(0, 40);
  if (!list.length) {
    host.innerHTML = '<div class="px-3 py-6 text-center text-sm text-tertiary">无匹配项</div>';
    return;
  }
  host.innerHTML = list.map(t => `
    <button data-id="${esc(t.id)}" class="flex w-full items-center gap-3 rounded-lg px-3 py-2 text-start hover:bg-secondary-ghost-hover">
      <span class="min-w-0 flex-1">
        <span class="block truncate text-sm text-default">${esc(threadTitle(t))}</span>
        <span class="block truncate text-xs text-tertiary">${esc(shortPath(t.cwd) || '')} · ${esc(relTime(t.updatedAt))}</span>
      </span>
      <span class="shrink-0 text-xs text-tertiary">${t.items} 条</span>
    </button>`).join('');
  host.querySelectorAll('[data-id]').forEach(b => {
    b.addEventListener('click', () => {
      location.hash = '#/t/' + b.dataset.id;
      closeSearch();
    });
  });
}

function openSearch() {
  const d = $('#search-dialog');
  d.classList.remove('hidden');
  const i = $('#search-input');
  i.value = '';
  renderSearchResults('');
  i.focus();
}

function closeSearch() {
  $('#search-dialog').classList.add('hidden');
}

/* --------------------------------------------------------------- topbar/keys */
function wireTopbar() {
  const bar = $('#topbar-slot');
  // menu buttons: 文件 / 编辑 / 视图 / 帮助
  $$('button', bar).forEach(b => {
    const label = (b.textContent || '').trim();
    if (['文件', '编辑', '视图', '帮助'].includes(label)) {
      b.addEventListener('click', () => {
        const items = {
          '文件': ['新聊天', '打开项目…', '设置…', '退出'],
          '编辑': ['撤销', '重做', '查找', '全选'],
          '视图': ['切换浅色/深色', '实际大小', '放大', '缩小'],
          '帮助': ['文档', '键盘快捷键', '关于 ChatGPT'],
        }[label] || [];
        openMenu(b, items);
      });
    }
  });
}

function wireHomeComposer() {
  wireComposer($('#home-view'));
}

function wireProfileMenu() {
  const aside = $('aside');
  if (!aside) return;
  const btn = Array.from(aside.querySelectorAll('button')).find(b => /个人资料菜单/.test(b.getAttribute('aria-label') || ''));
  if (!btn) return;
  btn.addEventListener('click', (e) => {
    e.preventDefault();
    openSettings();
  });
}

function wireSidebarNav() {
  const aside = $('aside');
  if (!aside) return;
  for (const b of $$('[data-sidebar-destination]', aside)) {
    const dest = b.getAttribute('data-sidebar-destination');
    if (dest === 'builtin:home') {
      b.addEventListener('click', () => { location.hash = ''; });
    }
  }
}

function wireGlobalKeys() {
  window.addEventListener('keydown', (e) => {
    const mod = e.ctrlKey || e.metaKey;
    if (mod && e.key.toLowerCase() === 'k') { e.preventDefault(); openSearch(); }
    if (mod && e.key.toLowerCase() === 'b') { e.preventDefault(); toggleSidebar(); }
    if (mod && e.shiftKey && e.key.toLowerCase() === 'l') { e.preventDefault(); toggleTheme(); }
    if (e.key === 'Escape') closeSearch();
  });
}

function attachScrollPill() {
  const tr = $('#transcript');
  if (!tr || tr.dataset.pillWired) return;
  tr.dataset.pillWired = '1';
  tr.addEventListener('scroll', () => {
    const nearBottom = tr.scrollHeight - tr.scrollTop - tr.clientHeight < 120;
    const pill = $('#scroll-pill');
    if (pill) pill.classList.toggle('hidden', nearBottom);
  });
}

function toggleTheme() {
  state.theme = state.theme === 'dark' ? 'light' : 'dark';
  document.documentElement.setAttribute('data-theme', state.theme);
  localStorage.setItem('replica-theme', state.theme);
}

function toggleSidebar() {
  const aside = $('aside');
  if (!aside) return;
  const collapsed = aside.dataset.collapsed === 'true';
  aside.dataset.collapsed = collapsed ? 'false' : 'true';
  aside.style.width = collapsed ? '340px' : '56px';
  const panel = aside.querySelector('div[style*="width: 340px"]');
  if (panel) panel.style.display = collapsed ? '' : 'none';
}

/* ---------------------------------------------------------------- scroll pill */
function ensureScrollPill() {
  if ($('#scroll-pill')) return;
  const pill = document.createElement('button');
  pill.id = 'scroll-pill';
  pill.className = 'hidden fixed bottom-28 left-1/2 -translate-x-1/2 z-30 flex items-center gap-1.5 rounded-full border border-subtle bg-surface-elevated-secondary px-3 py-1.5 text-xs shadow-lg';
  pill.innerHTML = `最新一条回复 ${ICON.arrowDown}`;
  pill.addEventListener('click', () => {
    const tr = $('#transcript');
    tr.scrollTop = tr.scrollHeight;
  });
  document.body.appendChild(pill);
}

/* --------------------------------------------------------------------- start */
const urlTheme = new URLSearchParams(location.search).get('theme');
const savedTheme = urlTheme || localStorage.getItem('replica-theme');
if (savedTheme === 'dark' || savedTheme === 'light') {
  state.theme = savedTheme;
  document.documentElement.setAttribute('data-theme', savedTheme);
}

boot().then(() => {
  ensureScrollPill();
}).catch(err => {
  console.error(err);
  document.body.insertAdjacentHTML('beforeend',
    `<pre style="position:fixed;left:12px;bottom:12px;z-index:9999;background:#300;color:#fdd;padding:10px;border-radius:8px;font:12px/1.4 monospace;max-width:60vw;overflow:auto">${esc(err && err.stack || err)}</pre>`);
});


/* Minimal glue so the real stylesheet drives a static, data-bound app. */

html, body {
  height: 100%;
  margin: 0;
  overflow: hidden;
  background: var(--color-background-primary, #fff);
  color: var(--color-text, #0d0d0d);
  font-family: var(--font-sans, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif);
}

#root { height: 100%; }
#shell { height: 100%; }

/* the app's PageSurface normally comes from its own layout component */
#page-surface {
  min-width: 0;
  position: relative;
}

/* home view: the extracted home layout is height-driven; give it room */
#home-view { min-height: 0; }
#home-view > .contents > .contents { height: 100%; }

/* thread view */
#thread-view { min-height: 0; }
#transcript { min-height: 0; }

/* sidebar keeps its own width; avoid the app's responsive collapse fighting us */
aside.app-shell-left-panel { flex: 0 0 auto; order: -1; }

/* contenteditable placeholder support (the app's ProseMirror normally does this) */
[contenteditable="true"]:empty::before,
[contenteditable="true"] p[data-placeholder]::before {
