/* Match the reference editor and context backing, using only real workspace data. */
.composer-wrap { flex: none; width: 100%; padding: 0 24px 20px; }
.composer-stack { width: 100%; max-width: 736px; margin-inline: auto; }
.composer-context { display: flex; align-items: center; gap: 20px; min-height: 54px; margin: 0 12px -14px; padding: 10px 16px 24px; border-radius: 20px 20px 0 0; background: var(--app-color-background-surface-under); color: var(--color-text-secondary); font-size: 12px; line-height: 20px; }
.composer-context > span { display: inline-flex; align-items: center; gap: 6px; min-width: 0; }
.composer-context svg { flex: none; width: 16px; height: 16px; }
