.composer { position: relative; z-index: 1; min-height: 98px; width: 100%; margin: 0 auto; padding: 12px 12px 8px; border: 1px solid var(--color-border); border-radius: 22px; background: var(--app-color-background-surface); box-shadow: 0 2px 6px var(--color-shadow-soft); }
.composer textarea { display: block; width: 100%; height: 40px; min-height: 40px; max-height: 180px; padding: 0; border: 0; outline: none; resize: none; background: transparent; color: var(--color-text); font-size: 14px; line-height: 20px; }
.composer textarea::placeholder { color: var(--muted); }
.composer-bottom { display: flex; align-items: center; gap: 12px; height: 28px; margin-top: 8px; font-size: 13px; line-height: 18px; color: var(--muted); }
.composer-keyboard { min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; color: var(--muted); font-size: 11px; line-height: 18px; }
.send-button { display: grid; place-items: center; flex: none; width: 28px; height: 28px; margin-left: auto; padding: 0; border: 0; border-radius: 50%; background: var(--color-text); color: var(--app-color-background-surface); font-size: 20px; line-height: 1; }
.send-button:disabled { opacity: 1; background: var(--color-background-secondary-ghost-hover); color: var(--muted); }
.composer { max-width: 736px; }
.home-state .composer-wrap { padding-bottom: 16px; }
.send-error, .action-error { margin: 8px auto 0; color: var(--color-status-error); font-size: 12px; line-height: 18px; overflow-wrap: anywhere; }
.action-error { padding: 0 24px 8px; }
.new-messages { position: absolute; z-index: 3; bottom: var(--composer-bottom-offset,172px); left: 50%; transform: translateX(-50%); padding: 6px 12px; border: 1px solid var(--color-border); border-radius: 999px; background: var(--app-color-background-surface); box-shadow: var(--shadow-lg); font-size: 12px; line-height: 18px; white-space: nowrap; }
.maintenance-banner { padding: 10px 24px; background: var(--app-color-background-surface-under); border-bottom: 1px solid var(--color-border-subtle); color: var(--muted); font-size: 12px; line-height: 18px; }

/* Activity is text; only concrete resources and terminal output use cards. */
.event-group { margin: 0 auto 24px; color: var(--muted); }
.event-line { margin: 0; }
.event-group > summary, .event-line > summary { display: inline-flex; align-items: center; gap: 4px; max-width: 100%; height: 21px; padding: 0; border: 0; border-radius: 0; background: none; color: var(--muted); font-size: 14px; line-height: 21px; font-weight: 400; cursor: pointer; list-style: none; }
.event-group > summary::-webkit-details-marker, .event-line > summary::-webkit-details-marker { display: none; }
.event-group > summary:hover, .event-line > summary:hover { color: var(--color-text); }
.event-group > summary svg, .event-line > summary svg { width: 16px; height: 16px; flex: none; }
.event-label { min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.event-mode { color: inherit; font-size: 12px; }
.event-failed { color: var(--color-status-error); }
.event-line.unknown .event-failed { color: var(--color-status-warning); }
[data-chevron] { opacity: .7; transition: transform var(--transition-duration-basic) var(--ease-out); }
[aria-expanded="true"] > [data-chevron] { transform: rotate(90deg); }
.detail-collapsible { overflow: hidden; height: 0; opacity: 0; margin-inline-start: -8px; padding-inline-start: 8px; transition: height var(--transition-duration-basic) var(--ease-out), opacity var(--transition-duration-basic) var(--ease-out); }
.event-detail { display: flex; flex-direction: column; gap: 12px; padding: 12px 0 0 24px; border: 0; background: none; color: var(--muted); font-size: 13px; line-height: 20px; }
.event-line .event-detail { gap: 8px; padding: 8px 0 4px 24px; }
.event-record > summary { display: inline-flex; align-items: center; gap: 4px; height: 21px; padding: 0; color: var(--muted); font-size: 14px; line-height: 21px; list-style: none; }
.event-record > summary::-webkit-details-marker { display: none; }
.event-record > summary:hover { color: var(--color-text); }
.event-record > summary svg { width: 16px; height: 16px; flex: none; }
.event-record-content { display: flex; flex-direction: column; gap: 8px; padding: 8px 0 4px 24px; }
.event-origin { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; font-size: 12px; line-height: 18px; }
.event-detail p { margin: 0; }
