.vertical-scroll-fade-mask { --edge-fade-distance: 2rem; mask-image: linear-gradient(to bottom, transparent 0, var(--color-mask-solid) var(--edge-fade-distance), var(--color-mask-solid) calc(100% - var(--edge-fade-distance)), transparent 100%); }
.resource-card { display: flex; align-items: center; gap: 12px; padding: 12px; min-width: 0; border: 1px solid var(--color-border-subtle); border-radius: 12.5px; background: var(--app-color-background-surface-under); }
