.timeline-update { display: flex; align-items: center; justify-content: space-between; gap: 12px; width: 100%; margin: 8px 0; padding: 12px; text-align: left; border: 1px solid var(--color-border-subtle); border-radius: 12.5px; background: var(--app-color-background-surface); }
.timeline-update:hover { background: var(--color-background-secondary-ghost-hover); }
.timeline-update strong, .timeline-update small { display: block; overflow-wrap: anywhere; }
