.settings-page-title { flex: none; margin: 0; font-size: 18px; line-height: 26px; font-weight: 500; }
.settings-search { display: flex; align-items: center; gap: 8px; height: 34px; flex: none; margin-top: -8px; padding: 6px 12px; border: 1px solid transparent; border-radius: 18px; background: var(--color-background-nav-active); color: var(--muted); }
.settings-search svg { flex: none; width: 16px; height: 16px; }
