.settings-nav-section { display: flex; flex-direction: column; gap: 1px; }
.settings-search + .settings-nav-section { margin-top: -4px; }
.settings-nav-group { margin: 0; padding: 0 8px 4px; font-size: 14px; line-height: 21px; font-weight: 500; color: var(--muted); }
.settings-nav-item { display: flex; align-items: center; gap: 8px; width: 100%; height: 30px; padding: 5px 8px; border: 0; border-radius: 12.5px; background: none; text-align: start; font-size: 13px; line-height: 18.5714px; }
.settings-nav-item:hover { background: var(--color-background-secondary-ghost-hover); }
.settings-nav-item.active { background: var(--color-background-nav-active); }
