function showHome() {
  state.view = 'home';
  state.currentId = null;
  state.current = null;
  $('#home-view').style.display = 'flex';
  $('#thread-view').style.display = 'none';
  const sv = $('#settings-view'); if (sv) sv.style.display = 'none';
  document.title = 'ChatGPT';
  markSelected(null);
  const host = $('aside [class*="nav-section-title"]')?.parentElement;
  if (host) renderAgentSection(host, (l, e) => {
    const d = document.createElement('div');
    d.className = 'group/nav-section-title flex min-h-[var(--height-token-row)] items-center justify-between gap-2 ps-2 pe-1.5 pt-2 pb-1 select-none';
    d.innerHTML = `<div class="min-w-0 flex-1 text-base font-medium text-tertiary">${esc(l)}</div>`;
    return d;
  }, null);
}

async function openThread(id) {
  if (state.currentId === id && state.view === 'thread') return;
  const res = await fetch(`/data/threads/${encodeURIComponent(id)}.json`);
  if (!res.ok) {
    showHome();
    return;
  }
  const doc = await res.json();
  state.current = doc;
  state.currentId = id;
  state.view = 'thread';
  state.turnsShown = 30;

  $('#home-view').style.display = 'none';
  $('#thread-view').style.display = 'flex';
  const sv = $('#settings-view'); if (sv) sv.style.display = 'none';
  document.title = threadTitle(doc) + ' — ChatGPT';

  renderThreadHeader(doc);
  renderTranscript(doc);
  ensureThreadComposer();
  buildSidebar();
  markSelected(id);

  const tr = $('#transcript');
  if (tr) tr.scrollTop = tr.scrollHeight;
  attachScrollPill();
  const pill = $('#scroll-pill');
  if (pill) pill.classList.add('hidden');
}

function markSelected(id) {
  for (const row of $$('[data-app-action-sidebar-thread-row]')) {
    const rid = (row.getAttribute('data-thread-id') || '');
    row.setAttribute('data-app-action-sidebar-thread-selected', rid && rid === id ? 'true' : 'false');
  }
}

/* --------------------------------------------------------------- transcript */
function ensureThreadComposer() {
  const slot = $('#thread-composer-slot');
  if (slot.dataset.ready) return;
  const src = $('#home-view [data-composer-input-layout]');
  if (!src) return;
  // climb to the composer frame (the bordered rounded box)
  let frame = src;
  for (let i = 0; i < 8 && frame.parentElement; i++) {
    const c = (frame.className || '').toString();
    if (/rounded/.test(c) && /border|shadow|bg-surface/.test(c)) break;
    frame = frame.parentElement;
  }
  const clone = frame.cloneNode(true);
  const holder = document.createElement('div');
  holder.className = 'mx-auto w-full max-w-[736px] px-6 pb-5 pt-1';
  holder.appendChild(clone);
  slot.innerHTML = '';
  slot.appendChild(holder);
  slot.dataset.ready = '1';
  wireComposer(slot);
}

